<script setup>
import {computed} from 'vue';
const props=defineProps({display:{type:Object,required:true}});
const extent=computed(()=>props.display.extent_m);
const viewBox=computed(()=>{const [x,y,xx,yy]=extent.value;return [x,y,xx-x,yy-y].join(' ');});
const flip=computed(()=>`translate(0 ${extent.value[1]+extent.value[3]}) scale(1 -1)`);
const points=rows=>rows.map(p=>p.join(',')).join(' ');
const cells=computed(()=>{const g=props.display.terrain?.grid;if(!g)return [];const values=g.elevation_m.flat(),lo=Math.min(...values),hi=Math.max(...values);return g.elevation_m.flatMap((row,y)=>row.map((z,x)=>({x:g.origin_m[0]+x*g.spacing_m[0],y:g.origin_m[1]+y*g.spacing_m[1],w:g.spacing_m[0],h:g.spacing_m[1],z,color:`hsl(${150-(z-lo)/Math.max(1,hi-lo)*115} 25% ${18+(z-lo)/Math.max(1,hi-lo)*24}%)`})));});
</script>
<template><section class="scene-preview panel" aria-label="场景输入预览"><div class="panelhead"><h3>100km 场景输入 · 非运行轨迹</h3><span>{{display.coordinate_frame}} · m</span></div><svg :viewBox="viewBox" role="img" aria-label="场景道路地形与设施"><defs><clipPath id="domain-clip"><rect :x="extent[0]" :y="extent[1]" :width="extent[2]-extent[0]" :height="extent[3]-extent[1]"/></clipPath></defs><g :transform="flip" clip-path="url(#domain-clip)"><rect :x="extent[0]" :y="extent[1]" :width="extent[2]-extent[0]" :height="extent[3]-extent[1]" fill="#15313a"/><rect v-for="(c,i) in cells" :key="i" :x="c.x" :y="c.y" :width="c.w" :height="c.h" :fill="c.color"><title>合成高程 {{c.z}} m · 仅展示</title></rect><polygon v-for="c in display.cities" :key="c.id" :points="points(c.polygon_m)" fill="#b8a782" fill-opacity=".3" stroke="#b8a782" vector-effect="non-scaling-stroke"><title>{{c.label}} · synthetic</title></polygon><polygon v-for="r in display.rivers" :key="r.id" :points="points(r.polygon_m)" fill="#3285ab"><title>{{r.id}} · synthetic</title></polygon><polyline v-for="r in display.roads" :key="r.edge_id" :points="points(r.points)" fill="none" stroke="#a7bac1" stroke-width="1" vector-effect="non-scaling-stroke"><title>{{r.edge_id}} · {{r.road_class}}</title></polyline><polyline v-for="b in display.bridges" :key="b.id" :points="points(b.line_m)" fill="none" stroke="#ffd276" stroke-width="3" vector-effect="non-scaling-stroke"><title>{{b.id}} · synthetic bridge</title></polyline><rect v-for="d in display.depots" :key="d.depot_id" :x="d.position_m.x_m-450" :y="d.position_m.y_m-450" width="900" height="900" fill="#63e4d0"><title>基地 {{d.depot_id}}</title></rect><circle v-for="w in display.wells" :key="w.well_id" :cx="w.position_m.x_m" :cy="w.position_m.y_m" r="500" fill="#d7a8ff"><title>井 {{w.well_id}} · 视图位置</title></circle><circle v-for="v in display.vehicles" :key="v.vehicle_id" :cx="v.position_m.x_m" :cy="v.position_m.y_m" r="330" fill="#ffd276"><title>车辆 {{v.vehicle_id}} · 初始输入位置</title></circle></g></svg><p>青色基地 · 紫色井场 · 黄色车辆初始位置/桥梁。预览不生成运行轨迹或污染浓度。</p><p v-if="display.terrain">SYNTHETIC 地形：平原 / 山坡 / 山地 · 高程仅用于展示，未参与 SUMO 车辆动力学或地下水物理参数。</p><p v-else>未取得的地形、道路或设施保持空缺；不从另一场景补充。</p><p v-if="display.hydro_placement">水文安置仅为 view-only 合成旋转/平移，原网格与物理井位保持不变。</p></section></template>
